public void updateBalance(Long id, BigDecimal delta) {
    int maxRetries = 3;
    for (int attempt = 0; attempt < maxRetries; attempt++) {
        try {
            Account account = session.find(Account.class, id); // swieza wersja
            account.setBalance(account.getBalance().add(delta));
            session.getTransaction().commit();
            return; // sukces
        } catch (OptimisticLockException e) {
            session.getTransaction().begin(); // sprobuj ponownie na swiezych danych
        }
    }
    throw new IllegalStateException("Nie udalo sie zapisac po " + maxRetries + " probach");
